input.command:
S=/private/tmp/wsbox/w-20261005-191428-b45f/scratchpad; W="$S/wt88"; mkdir -p "$S/shim" "$S/tmp"
cat > "$S/shim/mktemp" <<'SH'
#!/bin/sh
# test shim: a bare `mktemp -d` or `mktemp` lands in the scratchpad; anything else passes through
d=/private/tmp/wsbox/w-20261005-191428-b45f/scratchpad/tmp
case "$*" in
  -d) exec /usr/bin/mktemp -d "$d/tmp.XXXXXXXXXX" ;;
  "") exec /usr/bin/mktemp "$d/tmp.XXXXXXXXXX" ;;
  *) exec /usr/bin/mktemp "$@" ;;
esac
SH
chmod +x "$S/shim/mktemp"; which mktemp; export PATH="$S/shim:$PATH"; cd "$W" || exit 1
for t in tests/hooks/delegation.sh tests/shellcheck/gate.sh tests/spec-review/review-comment.sh tests/spec-review/review-brief.sh tests/poteto-mode/overlap.sh; do printf '%s: ' "$t"; bash "$t" 2>&1 | tail -1; done

